from flask import Flask, request, jsonify

app = Flask(__name__)

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Clipz.me — AI clipping studio</title><style>
:root{color-scheme:dark;--bg:#0b0b10;--panel:#14141d;--line:#292936;--muted:#9b9bad;--purple:#a78bfa;--white:#f8f7ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0%,#251747 0,transparent 34%),var(--bg);color:var(--white);font:15px Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;min-height:100vh}.wrap{max-width:1050px;margin:auto;padding:28px 22px}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:22px}.brand{display:flex;align-items:center;gap:12px;font-size:23px;font-weight:800;letter-spacing:-.8px}.logo{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:var(--purple);color:#171121;font-size:22px}.tag{color:#c4b5fd;background:#241b38;border:1px solid #40315e;padding:7px 11px;border-radius:999px;font-size:12px}.hero{padding:62px 0 32px;max-width:700px}.eyebrow{color:#c4b5fd;text-transform:uppercase;letter-spacing:2px;font-size:11px;font-weight:800}.hero h1{font-size:clamp(38px,7vw,64px);line-height:1.03;letter-spacing:-2.7px;margin:16px 0}.hero h1 span{color:var(--purple)}.hero p{color:var(--muted);font-size:17px;line-height:1.7;max-width:590px}.panel{background:#12121a;border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 25px 80px #0004}.panel h2{font-size:18px;margin:0 0 7px}.sub{color:var(--muted);margin:0 0 23px;font-size:13px}.tabs{display:flex;gap:8px;margin-bottom:14px}.tab{border:1px solid var(--line);border-radius:10px;background:#191923;color:#b9b9c8;padding:10px 15px;cursor:pointer}.tab.active{background:#2a2040;border-color:#8061bf;color:#eee7ff}.field{width:100%;background:#0c0c12;border:1px solid #333342;border-radius:11px;padding:15px;color:white;font-size:14px;outline:none}.field:focus{border-color:var(--purple)}.settings{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:17px 0}.label{display:block;color:#b6b6c6;font-size:12px;margin-bottom:8px}.primary{width:100%;border:0;border-radius:11px;padding:15px;background:var(--purple);color:#171121;font-weight:800;font-size:15px;cursor:pointer}.primary:hover{background:#bba6ff}.note{font-size:12px;color:#858598;text-align:center;margin-top:14px;line-height:1.6}.features{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-top:20px}.feature{border:1px solid var(--line);border-radius:15px;padding:18px;background:#111119}.feature b{display:block;margin:9px 0 6px}.feature p{font-size:12px;line-height:1.6;color:var(--muted);margin:0}.ico{font-size:22px}.status{display:none;margin-top:15px;padding:12px;border-radius:10px;background:#1d1930;color:#d9ccff;font-size:13px;line-height:1.5}footer{color:#6e6e80;font-size:12px;margin-top:38px;padding:20px 0;border-top:1px solid var(--line)}@media(max-width:650px){.wrap{padding:18px 14px}.hero{padding:42px 0 24px}.panel{padding:17px}.settings,.features{grid-template-columns:1fr}.hero h1{letter-spacing:-1.7px}.tag{display:none}}
</style></head><body><main class="wrap"><header class="top"><div class="brand"><div class="logo">✂</div>Clipz.me</div><div class="tag">✦ AI CLIPPING STUDIO</div></header><section class="hero"><div class="eyebrow">Your content, on autopilot</div><h1>Long videos.<br><span>Big moments.</span></h1><p>Turn YouTube videos and Twitch streams into short, punchy clips with AI-selected highlights, synced captions, and perfectly timed emojis.</p></section><section class="panel"><h2>Start clipping</h2><p class="sub">Drop a video link and choose how your clips should look.</p><div class="tabs"><button class="tab active" data-source="YouTube">▶ YouTube</button><button class="tab" data-source="Twitch">◉ Twitch</button></div><form id="clipform"><input class="field" id="url" type="url" placeholder="Paste a YouTube video URL…" required><div class="settings"><div><label class="label" for="count">Number of clips</label><select class="field" id="count"><option>3 clips</option><option selected>5 clips</option><option>10 clips</option></select></div><div><label class="label" for="style">Caption style</label><select class="field" id="style"><option selected>Dynamic</option><option>Minimal</option><option>Bold</option></select></div></div><button class="primary" type="submit">✦ Find my best moments</button></form><div class="status" id="status"></div><p class="note">Prototype dashboard · Video processing is not connected yet. Next we'll add the clipping worker and caption pipeline.</p></section><section class="features"><article class="feature"><div class="ico">🎯</div><b>Smart highlights</b><p>Find funny reactions, punchlines, and high-energy moments.</p></article><article class="feature"><div class="ico">💬</div><b>Captions that pop</b><p>Sync subtitles and add context-aware emojis automatically.</p></article><article class="feature"><div class="ico">📱</div><b>Ready to post</b><p>Build toward vertical clips for Shorts, Reels, and TikTok.</p></article></section><footer>© 2026 Clipz.me · Create more from every moment.</footer></main><script>let source='YouTube';document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{source=b.dataset.source;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#url').placeholder=source==='YouTube'?'Paste a YouTube video URL…':'Paste a Twitch VOD URL…'}));document.querySelector('#clipform').addEventListener('submit',e=>{e.preventDefault();const u=document.querySelector('#url').value.trim();const valid=source==='YouTube'?/(youtube\.com|youtu\.be)/i.test(u):/twitch\.tv/i.test(u);const s=document.querySelector('#status');s.style.display='block';s.textContent=valid?'Your '+source+' link is ready for the next step. The AI processing backend still needs to be connected before clips can be generated.':'That link does not look like a '+source+' URL. Please check it and try again.'});</script></body></html>'''

@app.get('/')
def home():
    return PAGE

@app.get('/health')
def health():
    return jsonify(status='ok', app='Clipz.me', video_processing='not_configured')

if __name__ == '__main__':
    import os
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 10000)))
